const output = [];
const items = $input.all();

for (const item of items) {
  const binary = item.binary || {};
  const json = item.json;

  Object.keys(binary).forEach(key => {
    if (!key.startsWith("attachment_")) return;

    const file = binary[key];
    const ext = (file.fileExtension || "").toLowerCase();
    const mime = (file.mimeType || "").toLowerCase();
    const name = (file.fileName || file.filename || "").toLowerCase();

    const isImage = ["png","jpg","jpeg","gif","bmp","webp"].includes(ext) || mime.startsWith("image/");
    const isNoname = !name || name === "noname";

    if (isImage || isNoname) return;

    output.push({
      json: {
        emailId: json.id,
        subject: json.subject || json.Subject,
        from: json.from || json.From,
        filename: file.fileName || file.filename || "",
        mimeType: file.mimeType || "",
        originalKey: key
      },
      binary: {
        data: binary[key]
      }
    });
  });
}

return output;

const uploadedFiles = $json.uploadedFiles || [];

// Extract just the file IDs as a comma-separated string
const fileIds = uploadedFiles.map(f => f.id).join(',');

return {
  json: {
    fileIds: fileIds,
    fileCount: uploadedFiles.length,
    uploadedFiles: uploadedFiles
  }
};

