const response = $json;
const textContent = response?.output?.[0]?.content?.[0]?.text;

if (!textContent) {
  return [{ json: { error: "No response from AI", order_ref: "unknown" } }];
}

let orderData;
try {
  orderData = typeof textContent === "string" ? JSON.parse(textContent) : textContent;
} catch (e) {
  return [{ json: { error: "Invalid JSON from AI", order_ref: "unknown", raw: textContent } }];
}

if (!orderData.items || orderData.items.length === 0) {
  return [{ json: { error: "No items found in response", order_ref: orderData.order?.order_ref || "unknown" } }];
}

const orderRef = orderData.order?.order_ref || "unknown";
const orderDate = orderData.order?.order_date || "";
const orderTotal = orderData.order?.order_total || 0;
const currency = orderData.order?.currency || "EUR";
const customerName = orderData.order?.customer?.name || "";
const customerEmail = orderData.order?.customer?.email || "";
const customerPhone = orderData.order?.customer?.phone || "";
const customerAddress = orderData.order?.customer?.address || "";
const customerCounty = orderData.order?.customer?.county || "";
const accountRef = orderData.order?.customer?.account_ref || "";
const poNumber = orderData.order?.customer?.po_number || "";
const notes = orderData.order?.notes || "";

return orderData.items.map(item => ({
  json: {
    order_ref: orderRef,
    order_date: orderDate,
    order_total: orderTotal,
    currency: currency,
    customer_name: customerName,
    customer_email: customerEmail,
    customer_phone: customerPhone,
    customer_address: customerAddress,
    customer_county: customerCounty,
    account_ref: accountRef,
    po_number: poNumber,
    notes: notes,
    line_number: item.line_number,
    product_code: item.product_code,
    product_name: item.product_name,
    barcode: item.barcode,
    brand: item.brand,
    pack_size: item.pack_size,
    quantity: item.quantity,
    unit_price: item.unit_price,
    discount: item.discount,
    vat: item.vat,
    line_total: item.line_total
  }
}));

const fileIdsString = $('Prepare Messages').first().json.fileIds || "";

const fileIds = fileIdsString
  .split(",")
  .map(id => id.trim())
  .filter(id => id !== "");

const fileBlocks = fileIds.map(id => ({
  type: "file",
  file: { file_id: id }
}));

const body = {
  model: "gpt-4o-mini",
  temperature: 0,
  response_format: { type: "json_object" },
  messages: [
    {
      role: "system",
      content: "You are an order data extractor for Distinct Distribution, an Irish health and beauty distributor. Extract ALL line items from the document and return ONLY raw JSON. No explanation. No markdown. No code fences. Rules: extract EVERY row, numbers are always numbers never strings, dates as YYYY-MM-DD, missing fields use empty string or 0 never null."
    },
    {
      role: "user",
      content: [
        {
          type: "text",
          text: fileIds.length === 1 ? "Extract the order from this file and return JSON." : "Extract the order from these files and return JSON."
        },
        ...fileBlocks
      ]
    }
  ]
};

return [{ json: body }];

const response = $json;

const content = response?.[0]?.choices?.[0]?.message?.content
             || response?.choices?.[0]?.message?.content
             || "";

if (!content) {
  return [{
    json: {
      _meta: {
        error: true,
        error_reason: "No content in GPT response",
        parse_confidence: "LOW"
      },
      order: {},
      items: []
    }
  }];
}

let parsed;
try {
  parsed = JSON.parse(content);
} catch (e) {
  return [{
    json: {
      _meta: {
        error: true,
        error_reason: "Invalid JSON from GPT: " + e.message,
        parse_confidence: "LOW"
      },
      _raw: content,
      order: {},
      items: []
    }
  }];
}

if (!parsed.items || parsed.items.length === 0) {
  return [{
    json: {
      ...parsed,
      _meta: {
        error: true,
        error_reason: "No items found in extracted order",
        parse_confidence: "LOW"
      }
    }
  }];
}

return [{
  json: {
    order:     parsed.order,
    items:     parsed.items,
    _meta:     parsed._meta,
    _model:    response?.[0]?.model    || response?.model    || "",
    _usage:    response?.[0]?.usage    || response?.usage    || {},
    _filename: $json.filename          || "",
    _emailId:  $json.emailId          || "",
  }
}];

