// ===============================
// N8N Code Node - Extract Order Details for GHL
// Processes ONE email per invocation (fed by Loop Over Orders)
// ===============================

// Get raw email text for the current item in the loop
const inputData = $input.first().json.text || "";

// ===============================
// Helper: Extract value after label
// ===============================
function extractValue(text, label) {
  const regex = new RegExp(label + ":\\s*(.*)", 'i');
  const match = text.match(regex);
  return match && match[1] ? match[1].trim() : "";
}

// ===============================
// Normalize broken item totals
// ===============================
let normalizedText = inputData.replace(/\n(\d+\.\d{2})\n/g, ' $1\n');

// ===============================
// Extract Customer Information
// ===============================
const customerInfo = {
  storeName: extractValue(normalizedText, 'Store Name'),
  contactName: extractValue(normalizedText, 'Contact Name'),
  phoneNumber: extractValue(normalizedText, 'Phone Number'),
  whatsappPhone: extractValue(normalizedText, 'WhatsApp Phone Number \\(Training & etc\\.\\)'),
  email: extractValue(normalizedText, 'E-mail'),
  accountNumber: extractValue(normalizedText, 'Pemberton Account Number'),
  shippingAddress: extractValue(normalizedText, 'Shipping Address'),
  country: extractValue(normalizedText, 'County \\(or choose outside Ireland\\)'),
  poNumber: extractValue(normalizedText, 'PO Number'),
  discountCode: extractValue(normalizedText, 'Discount Code')
};

// ===============================
// Extract Flipbook Info
// ===============================
const flipbookInfo = {
  title: extractValue(normalizedText, 'Flipbook title'),
  internalName: extractValue(normalizedText, 'Internal flipbook name'),
  url: extractValue(normalizedText, 'URL')
};

// ===============================
// Extract Order Items
// ===============================
const orderItems = [];
const lines = normalizedText.split('\n');

for (let line of lines) {
  const parts = line.trim().split(/\s+/);

  if (/^\d{6,}/.test(parts[0])) {
    const id = parts[0];

    const price = parseFloat(parts[parts.length - 3]);
    const qty = parseInt(parts[parts.length - 2]);
    const total = parseFloat(parts[parts.length - 1]);

    const name = parts.slice(1, parts.length - 3).join(' ');

    if (!isNaN(price) && !isNaN(qty) && !isNaN(total)) {
      orderItems.push({
        id,
        name,
        quantity: qty,
        unitPrice: price,
        totalPrice: total
      });
    }
  }
}

// ===============================
// Calculate Totals
// ===============================
const orderTotal = orderItems.reduce((sum, item) => sum + item.totalPrice, 0);
const itemCount = orderItems.length;
const totalUnits = orderItems.reduce((sum, item) => sum + item.quantity, 0);

// ===============================
// Structure GHL Contact
// ===============================
const ghlContact = {
  firstName: customerInfo.contactName.split(' ')[0] || "",
  lastName: customerInfo.contactName.split(' ').slice(1).join(' ') || "",
  email: customerInfo.email,
  phone: customerInfo.phoneNumber,
  source: 'Order System',
  tags: ['Customer', 'Order Placed'],
  customFields: {
    storeName: customerInfo.storeName,
    accountNumber: customerInfo.accountNumber,
    shippingAddress: customerInfo.shippingAddress,
    country: customerInfo.country,
    whatsappPhone: customerInfo.whatsappPhone
  }
};

// ===============================
// Structure GHL Opportunity
// ===============================
const ghlOpportunity = {
  name: "Order " + (customerInfo.poNumber || 'N/A') + " - " + customerInfo.storeName,
  pipelineStage: 'New Order',
  status: 'open',
  monetaryValue: orderTotal,
  contactEmail: customerInfo.email,
  customFields: {
    poNumber: customerInfo.poNumber,
    orderTotal: orderTotal,
    itemCount: itemCount,
    totalUnits: totalUnits,
    discountCode: customerInfo.discountCode,
    flipbookTitle: flipbookInfo.title,
    flipbookUrl: flipbookInfo.url,
    accountNumber: customerInfo.accountNumber
  },
  notes: "Order Details:\n" + orderItems.map(item => "- " + item.name + ": " + item.quantity + " x " + item.unitPrice + " = " + item.totalPrice).join('\n') + "\n\nTotal: " + orderTotal
};

// ===============================
// Return Structured Output
// ===============================
return {
  json: {
    customerInfo,
    flipbookInfo,
    orderItems,
    orderSummary: {
      poNumber: customerInfo.poNumber,
      total: orderTotal,
      itemCount,
      totalUnits,
      discountCode: customerInfo.discountCode
    },
    ghlContact,
    ghlOpportunity,
    rawData: inputData
  }
};

const items = $input.all();
const orderData = $("Parse iPaper Order Email Text").first().json;

const orderRef = orderData.orderSummary?.poNumber || "";
const orderDate = new Date().toISOString().split("T")[0];
const customerName = orderData.customerInfo?.contactName || "";

return items.map((item, index) => ({
  json: {
    order_ref: orderRef,
    order_date: orderDate,
    customer_name: customerName,
    line_number: index + 1,
    product_code: item.json.id || "",
    product_name: item.json.name || "",
    barcode: "",
    brand: "",
    pack_size: 0,
    quantity: item.json.quantity || 0,
    unit_price: item.json.unitPrice || 0,
    discount: 0,
    vat: 0,
    line_total: item.json.totalPrice || 0
  }
}));
